import React, { useState } from 'react';
import { db } from '../lib/firebase';
import {
    doc,
    updateDoc,
    deleteDoc,
    serverTimestamp
} from 'firebase/firestore';
import { BlogPostEditor } from './BlogPostEditor';
import { ConfirmModal } from './ui/ConfirmModal';

import { BlogPost, LanguageCode } from '../types';
import { User as FirebaseUser } from 'firebase/auth'; // Assuming User is needed or used as 'any' currently

interface BlogManagerProps {
    posts: any[];
    t: any;
    onRefresh: () => void;
    profile: any;
    user: any;
    lang: LanguageCode;
}

export const BlogManager: React.FC<BlogManagerProps> = ({ posts, t, onRefresh, profile, user, lang }) => {
    const [showEditor, setShowEditor] = useState(false);
    const [editingPost, setEditingPost] = useState<any | null>(null);
    const [confirmModal, setConfirmModal] = useState<{
        isOpen: boolean;
        title: string;
        message: string;
        onConfirm: () => void;
        isDestructive: boolean;
        confirmText: string;
    }>({
        isOpen: false,
        title: '',
        message: '',
        onConfirm: () => {},
        isDestructive: true,
        confirmText: 'Delete'
    });

    const canManage = (post: any) => {
        if (!profile) return false;
        if (profile.role === 'admin') return true;
        return post.author_id === profile.id;
    };

    const deletePost = async (id: string) => {
        setConfirmModal({
            isOpen: true,
            title: 'Delete Story',
            message: 'Are you sure you want to permanently delete this story? This action cannot be undone.',
            confirmText: 'Delete',
            isDestructive: true,
            onConfirm: async () => {
                try {
                    await deleteDoc(doc(db, 'blog_posts', id));
                    onRefresh();
                } catch (err: any) {
                    console.error('Error deleting story:', err);
                    alert(`Delete failed: ${err.message}`);
                }
                setConfirmModal(prev => ({ ...prev, isOpen: false }));
            }
        });
    };

    const updateStatus = async (id: string, status: 'approved' | 'rejected') => {
        try {
            await updateDoc(doc(db, 'blog_posts', id), {
                status,
                updated_at: serverTimestamp()
            });
            onRefresh();
        } catch (err: any) {
            alert(`Moderation failed: ${err.message}`);
        }
    };

    const startEdit = (post: any) => {
        setEditingPost(post);
        setShowEditor(true);
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-xl font-semibold text-slate-900 uppercase">
                    {t.blog || 'Community Stories'}
                </h2>

                <button
                    onClick={() => {
                        setEditingPost(null);
                        setShowEditor(true);
                    }}
                    className="bg-primary text-white px-6 py-2.5 rounded-xl text-xs font-semibold uppercase tracking-wide shadow-lg shadow-primary/20 hover:scale-105 transition-all"
                >
                    Share New Story
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {posts.length === 0 ? (
                    <div className="col-span-full py-20 text-center text-slate-300 font-semibold uppercase tracking-wide">No stories yet</div>
                ) : posts.map((p: any) => (
                    <div key={p.id} className="relative bg-white p-5 rounded-[2rem] border border-slate-200 flex flex-col gap-4 group hover:shadow-xl hover:shadow-slate-200/50 transition-all">
                        <div className="flex items-start gap-4">
                            <div className="size-16 rounded-2xl overflow-hidden bg-slate-100 flex-shrink-0 border border-slate-100">
                                {(() => {
                                    let urls = [];
                                    try {
                                        const raw = p.media_urls || p.media;
                                        if (Array.isArray(raw)) urls = raw;
                                        else if (typeof raw === 'string' && raw.startsWith('[')) urls = JSON.parse(raw);
                                        else if (typeof raw === 'string') urls = [raw];
                                    } catch (e) { }

                                    const firstImg = urls?.[0];
                                    const resolveUrl = (url: string) => {
                                        if (!url || typeof url !== 'string') return '';
                                        if (url.startsWith('http')) return url;
                                        return url;
                                    };

                                    return firstImg ? (
                                        <img src={resolveUrl(firstImg)} className="w-full h-full object-cover" onError={(e: any) => e.target.src = 'https://placehold.co/200x200/f1f5f9/94a3b8?text=?'} />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center text-slate-300">
                                            <span className="material-symbols-outlined text-xl">auto_stories</span>
                                        </div>
                                    );
                                })()}
                            </div>
                            <div className="flex-1 min-w-0 pr-24">
                                <h4 className="font-semibold text-slate-900 text-base truncate">{p.title}</h4>
                                <div className="flex items-center gap-2 mt-1">
                                    <span className={`text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-md ${p.status === 'approved' ? 'bg-emerald-50 text-emerald-600' : 'bg-amber-50 text-amber-600'}`}>
                                        {p.status}
                                    </span>
                                    <span className="w-1 h-1 rounded-full bg-slate-300"></span>
                                    <span className="text-[10px] font-bold text-primary bg-primary/5 px-2 py-0.5 rounded-md uppercase tracking-wider truncate">{p.category}</span>
                                </div>
                            </div>
                        </div>

                        <div className="flex flex-col gap-1 mt-auto">
                            <p className="text-xs font-medium text-slate-400 uppercase tracking-wide">{new Date(p.created_at).toLocaleDateString()}</p>
                            {p.profiles?.full_name && (
                                <span className="text-xs font-semibold text-primary uppercase tracking-tight">by {p.profiles.full_name}</span>
                            )}
                        </div>

                        {profile?.role === 'admin' && p.status === 'pending_approval' && (
                            <div className="flex gap-2 w-full mt-2">
                                <button
                                    onClick={() => updateStatus(p.id, 'approved')}
                                    className="flex-1 px-4 py-2.5 bg-emerald-500 text-white rounded-xl text-xs font-semibold uppercase hover:bg-emerald-600 transition-all shadow-lg shadow-emerald-500/20"
                                >
                                    Approve
                                </button>
                                <button
                                    onClick={() => updateStatus(p.id, 'rejected')}
                                    className="flex-1 px-4 py-2.5 bg-white border border-amber-200 text-amber-600 rounded-xl text-xs font-semibold uppercase hover:bg-amber-50 transition-all"
                                >
                                    Reject
                                </button>
                            </div>
                        )}

                        <div className="absolute top-4 right-4 flex flex-row gap-2 opacity-100 transition-opacity">
                            {canManage(p) && (
                                <>
                                    <button onClick={() => startEdit(p)} className="p-2 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-primary hover:border-primary/20 shadow-sm transition-all">
                                        <span className="material-symbols-outlined text-[18px]">edit</span>
                                    </button>
                                    <button onClick={() => deletePost(p.id)} className="p-2 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-red-500 hover:border-red-200 shadow-sm transition-all">
                                        <span className="material-symbols-outlined text-[18px]">delete</span>
                                    </button>
                                </>
                            )}
                        </div>
                    </div>
                ))}
            </div>

            {showEditor && (
                <BlogPostEditor
                    lang={lang}
                    user={user}
                    post={editingPost}
                    onClose={() => setShowEditor(false)}
                    onSuccess={() => {
                        setShowEditor(false);
                        onRefresh();
                    }}
                />
            )}

            <ConfirmModal 
                isOpen={confirmModal.isOpen}
                onClose={() => setConfirmModal(prev => ({ ...prev, isOpen: false }))}
                onConfirm={confirmModal.onConfirm}
                title={confirmModal.title}
                message={confirmModal.message}
                confirmText={confirmModal.confirmText}
                isDestructive={confirmModal.isDestructive}
            />
        </div>
    );
};
